def render_x2(k, Ns, sym, P):
    P = dict(P)
    P['BGT'] = P['SUBS'] + 1
    P['EPI'] = P['SUBS'] + 2
    P['RETP1'] = P['RET'] + 1
    segs = ['GenSE1', 'GenSH', 'GenSHa', 'GenSHb', 'GenSHc', 'GenSBe', 'GenSBo', 'GenSX']
    imports = '\n'.join('import Keccaktree.Kernels.%s.InPlace.%s' % (Ns, s) for s in segs)
    out = HEAD.format(Ns=Ns, sym=sym, k=k, imports=imports, **P)
    for kind in 'abc':
        HX = {'a': 'GenSHa', 'b': 'GenSHb', 'c': 'GenSHc'}[kind]
        BX = 'GenSBo' if kind == 'c' else 'GenSBe'
        hyp = {'a': '(hr : 2 * k + 3 ≤ c)', 'b': '(hr : c = 2 * k + 2)', 'c': '(hr : c = 2 * k + 1)'}[kind]
        what = {'a': 'with r ≥ 3 nodes left', 'b': 'with two nodes left', 'c': 'with one node left (node 0 duplicated)'}[kind]
        ZV, CV, NV = {'a': ('false', 'true', 'false'), 'b': ('true', 'true', 'false'), 'c': ('false', 'false', 'true')}[kind]
        d = lambda v: 'decide_eq_true' if v == 'true' else 'decide_eq_false'
        out += BATCH.format(kind=kind, HX=HX, BX=BX, hyp=hyp, what=what, ZV=ZV, CV=CV, NV=NV, dz=d(ZV), dc=d(CV),
                            dn=d(NV), OUT=4 if kind == 'c' else 8, **P)
    out += TAIL.format(Ns=Ns, sym=sym, k=k, **P)
    return out

